#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Function executed by the detached thread
void *detached_thread_func(void *arg) {
    printf("Detached thread started (ID: %lu). Simulating work.\n", (unsigned long)pthread_self());
    sleep(1);
    printf("Detached thread exiting, resources automatically released.\n");
    return NULL;
}

int main(void) {
    pthread_attr_t attr;
    pthread_t thread_id;
    int s;

    // 1. Initialize the attributes object
    if ((s = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }

    // 2. Set the detach state to DETACHED
    printf("Setting thread detach state to PTHREAD_CREATE_DETACHED.\n");
    s = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    if (s != 0) {
        fprintf(stderr, "Error setting detach state: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 3. Create the thread using the detached attributes
    s = pthread_create(&thread_id, &attr, detached_thread_func, NULL);
    if (s != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Clean up the attributes object (it's copied during pthread_create)
    pthread_attr_destroy(&attr);

    // Note: We cannot join this thread. We must ensure main waits long enough
    // for the detached thread to complete its execution.
    printf("Main thread continues. Will sleep to allow detached thread time to finish.\n");
    sleep(2);

    return 0;
}
